INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',595,'{"_type":"chat:Message","id":"8641420749:1377","threadId":"telegram:8641420749","text":"Il va falloir que j’adapte au planning de la famille car on sera en vacances en famille pendant 10 jours à partir d’aujourd’hui. Donc donne moi les blocs importants a placer pendant ces 10 jours et le plan idéal sans contrainte. Ce qui est deja sur c’est que dimanche 30 on sera sur la route de retour a la maison donc pas possible de pedaler.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Il va falloir que j’adapte au planning de la famille car on sera en vacances en famille pendant 10 jours à partir d’aujourd’hui. Donc donne moi les blocs importants a placer pendant ces 10 jours et le plan idéal sans contrainte. Ce qui est deja sur c’est que dimanche 30 on sera sur la route de retour a la maison donc pas possible de pedaler.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":344,"offset":343}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":344,"offset":343}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":344,"offset":343}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-20T16:17:07.000Z","edited":false},"attachments":[],"isMention":false}',1787847426545);
