INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',636,'{"_type":"chat:Message","id":"8641420749:1465","threadId":"telegram:8641420749","text":"Dimanche voyage de retour donc pas possible de pedaler.\nLundi, mardi, mercredi, jeudi je vais faire un voyage a velo avec les enfants, ils seront dans la remorque et je serai seul. Donc je vais pouvoir rouler au moins 4h par jour avec eux.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Dimanche voyage de retour donc pas possible de pedaler.\nLundi, mardi, mercredi, jeudi je vais faire un voyage a velo avec les enfants, ils seront dans la remorque et je serai seul. Donc je vais pouvoir rouler au moins 4h par jour avec eux.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":184,"offset":239}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":184,"offset":239}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":184,"offset":239}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-27T11:56:07.000Z","edited":false},"attachments":[],"isMention":false}',1788436565892);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',637,'{"_type":"chat:Message","id":"8641420749:1468","threadId":"telegram:8641420749","text":"Attends, je te donne mes dispo pour les jours suivants. Donc je recapitule:\n• aujourd''hui jeudi dispo\n• demain vendredi pas dispo\n• samedi dispo\n• dimanche pas dispo\n• lundi, mardi, mercredi, jeudi au moins 4h par jour avec les enfants\n• vendredi dispo sans enfant\n• samedi dimanche pas dispo\n• lundi, mardi dispo\n• mercredi suivant pas dispo","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Attends, je te donne mes dispo pour les jours suivants. Donc je recapitule:\n• aujourd''hui jeudi dispo\n• demain vendredi pas dispo\n• samedi dispo\n• dimanche pas dispo\n• lundi, mardi, mercredi, jeudi au moins 4h par jour avec les enfants\n• vendredi dispo sans enfant\n• samedi dimanche pas dispo\n• lundi, mardi dispo\n• mercredi suivant pas dispo","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":10,"column":29,"offset":342}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":10,"column":29,"offset":342}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":10,"column":29,"offset":342}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-27T12:05:16.000Z","edited":false},"attachments":[],"isMention":false}',1788437113515);
