INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',649,'{"_type":"chat:Message","id":"8641420749:1496","threadId":"telegram:8641420749","text":"Je me suis réveillé avec le genou droit plus chaud que le genou gauche ce matin. Pas de douleur, juste chaud. J’ai mis de la glace pendant 15min.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je me suis réveillé avec le genou droit plus chaud que le genou gauche ce matin. Pas de douleur, juste chaud. J’ai mis de la glace pendant 15min.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":146,"offset":145}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":146,"offset":145}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":146,"offset":145}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-30T09:02:22.000Z","edited":false},"attachments":[],"isMention":false}',1788685341625);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',650,'{"_type":"chat:Message","id":"8641420749:1501","threadId":"telegram:8641420749","text":"Pour l’instant on change pas le plan macro. Je vais faire les 3-4 jours de velo avec les enfants et on verra ensuite comment on adapte en fonction de combien d’heures j’ai fait. \n\nPour le genou, hier j’ai pas fait de sprint, je ne chasse jamais de PR. Les pics c’etait de l’alternance assis debout dans les montées. Donc c’est normal, et ca n’impacte pas le genou. Hier, c’etait une sortie assez difficile de maniere generale, ca ne fait que monter et descendre par ici. Et le rythme moyen en montée etait legerement trop élevé donc un peu trop de pression sur les muscles des cuisses et genou.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Pour l’instant on change pas le plan macro. Je vais faire les 3-4 jours de velo avec les enfants et on verra ensuite comment on adapte en fonction de combien d’heures j’ai fait.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":178,"offset":177}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":179,"offset":178}}},{"type":"paragraph","children":[{"type":"text","value":"Pour le genou, hier j’ai pas fait de sprint, je ne chasse jamais de PR. Les pics c’etait de l’alternance assis debout dans les montées. Donc c’est normal, et ca n’impacte pas le genou. Hier, c’etait une sortie assez difficile de maniere generale, ca ne fait que monter et descendre par ici. Et le rythme moyen en montée etait legerement trop élevé donc un peu trop de pression sur les muscles des cuisses et genou.","position":{"start":{"line":3,"column":1,"offset":180},"end":{"line":3,"column":415,"offset":594}}}],"position":{"start":{"line":3,"column":1,"offset":180},"end":{"line":3,"column":415,"offset":594}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":415,"offset":594}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-30T11:24:02.000Z","edited":false},"attachments":[],"isMention":false}',1788693841000);
