INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',652,'{"_type":"chat:Message","id":"8641420749:1507","threadId":"telegram:8641420749","text":"Pas de renfo aujourd’hui. Ca va etre difficile pendant le voyage. Genou legerement chaud ce matin, moins qu’hier. Mais toujours 0/10","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Pas de renfo aujourd’hui. Ca va etre difficile pendant le voyage. Genou legerement chaud ce matin, moins qu’hier. Mais toujours 0/10","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":133,"offset":132}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":133,"offset":132}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":133,"offset":132}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-31T16:46:37.000Z","edited":false},"attachments":[],"isMention":false}',1788799597454);
