INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',654,'{"_type":"chat:Message","id":"8641420749:1514","threadId":"telegram:8641420749","text":"Les pics c’est des montées avec le kid trailer. Des que c’est plus que 3%, on dirait du 8-9% sans trailer. Ca fait monter direct la FC. Et aujourd’hui y’avait beaucoup de montées, c’etait dur avec le trailer. \nUpdate du voyage : je vais faire que 3 jours hier inclus, donc lundi-mercredi ca fera un bloc de 3 jours. Ensuite il faudra que je repose les jambes. Je sens que ces montées avec le trailer ca tire fort sur les genoux, il faudra que je les repose qlqs jours. Demain c’est 70km mais bcp moins de montées, 410m de D+","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Les pics c’est des montées avec le kid trailer. Des que c’est plus que 3%, on dirait du 8-9% sans trailer. Ca fait monter direct la FC. Et aujourd’hui y’avait beaucoup de montées, c’etait dur avec le trailer.\nUpdate du voyage : je vais faire que 3 jours hier inclus, donc lundi-mercredi ca fera un bloc de 3 jours. Ensuite il faudra que je repose les jambes. Je sens que ces montées avec le trailer ca tire fort sur les genoux, il faudra que je les repose qlqs jours. Demain c’est 70km mais bcp moins de montées, 410m de D+","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":315,"offset":524}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":315,"offset":524}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":315,"offset":524}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-01T19:11:48.000Z","edited":false},"attachments":[],"isMention":false}',1788894706892);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',655,'{"_type":"chat:Message","id":"8641420749:1517","threadId":"telegram:8641420749","text":"Genoux à 0/10, mais je sens que ça a tiré aujourd’hui. On verra s’il est chaud demain matin. Avec autant de Z3 et Z4 il faut pas que j’abuse pour pouvoir continuer avec le plan prévu dans qlqs jours.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Genoux à 0/10, mais je sens que ça a tiré aujourd’hui. On verra s’il est chaud demain matin. Avec autant de Z3 et Z4 il faut pas que j’abuse pour pouvoir continuer avec le plan prévu dans qlqs jours.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":200,"offset":199}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":200,"offset":199}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":200,"offset":199}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-01T19:16:13.000Z","edited":false},"attachments":[],"isMention":false}',1788894972626);
