INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',663,'{"_type":"chat:Message","id":"8641420749:1523","threadId":"telegram:8641420749","text":"Clean moi cette checklist pour l’envoyer a mes potes avec qui je vais faire M-N 2026\n\nChecklist Marseille Napoli 2025. Casque, casquette. Lumiere blanche Macro Drive 1400+ da Lezyne, 2 lumières rouge (2 car moins de batterie), 2 grandes gourde. Salt caps (2 par jours), GPS, portefeuille, lunettes avec verres de jour et verres de nuit, mitaine, ID, cache col. Écouteur. Changeur rapide. Deux chambres air. 2 jerseys. Mini trousse de toilettes. Un t-shirt de ski Odlo (si gros coup de froid, longue descente, soir ou matin, mais rarement utilisé). jersey manche longue gore bikewear un peu chaud. Deux paires de chaussettes. Jambieres. gants longs. Un Kway Decath a 20 balles parce que j’avais perdu ma putain de veste de pluie Peak Performance peu de temps avant , un cuissard. Chaussures. Gilet de visibilité. couverture de survie.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Clean moi cette checklist pour l’envoyer a mes potes avec qui je vais faire M-N 2026","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":85,"offset":84}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":85,"offset":84}}},{"type":"paragraph","children":[{"type":"text","value":"Checklist Marseille Napoli 2025. Casque, casquette. Lumiere blanche Macro Drive 1400+ da Lezyne, 2 lumières rouge (2 car moins de batterie), 2 grandes gourde. Salt caps (2 par jours), GPS, portefeuille, lunettes avec verres de jour et verres de nuit, mitaine, ID, cache col. Écouteur. Changeur rapide. Deux chambres air. 2 jerseys. Mini trousse de toilettes. Un t-shirt de ski Odlo (si gros coup de froid, longue descente, soir ou matin, mais rarement utilisé). jersey manche longue gore bikewear un peu chaud. Deux paires de chaussettes. Jambieres. gants longs. Un Kway Decath a 20 balles parce que j’avais perdu ma putain de veste de pluie Peak Performance peu de temps avant , un cuissard. Chaussures. Gilet de visibilité. couverture de survie.","position":{"start":{"line":3,"column":1,"offset":86},"end":{"line":3,"column":748,"offset":833}}}],"position":{"start":{"line":3,"column":1,"offset":86},"end":{"line":3,"column":748,"offset":833}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":748,"offset":833}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-01T21:13:16.000Z","edited":false},"attachments":[],"isMention":false}',1788901995143);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',664,'{"_type":"chat:Message","id":"8641420749:1525","threadId":"telegram:8641420749","text":"Voila ma checklist final, t''en penses quoi ? Il me manque des choses ? Des astuces et pro tricks pour de l''ultra ? On dort à l''hotel\n\n\n*Checklist Marseille Napoli 2025*\n🛡️ *Sécurité / visibilité* • Casque • Gilet de visibilité • Couverture de survie • Lumière avant : Lezyne Macro Drive 1400+ (!!!) • 2× lumière arrière rouge (car petites et moins de batterie) • ⁠Lunettes avec verres jour + verres nuit • ⁠Retro !!!!! (inclus lunettes)\n👕 *Vêtements* • 1x Gapette • 1x Cache-col • 1x Mitaines • 1x Gants longs (x2 si pluie prévue) • 1x Jambières • 2× paires de chaussettes • 2× jerseys • 1x Maillot manches longues Gore Bikewear (chaud) • 1x Cuissard • Chaussures • 1x T-shirt thermique Odlo (coup de froid, grande descente, matin/soir. Rarement utilisé, plutôt au cas où) • Kway Decath a 20 balles parce que j’avais perdu ma putain de veste de pluie Peak Performance peu de temps avant samairlapute • ⁠1x short de course à pied hyper leger que j’utilise pour dormir • ⁠1x legging Decath si grand froid ou soir (rarement utilisé ou pas utilisé je crois)\n💧 *Hydratation / nutrition* • 2 grandes gourdes • Salt caps (2/jour) • ⁠doses préparées de malto/fructo • ⁠qlqs gels (puis achetés en route)\n📱 *Tech* • GPS • Écouteurs • ⁠1 chargeur rapide (tel+GPS)\n🔧 *Mécanique* • 2 chambres à air • 1 multi tool • ⁠2 demonte pneus • ⁠1 pompe • ⁠2 capsules de CO2 • ⁠1 quick link\n📋 *Divers* • Portefeuille taille CB • Pièce d''identité • Mini trousse de toilette • ⁠Ibuprofene • ⁠Paracetamol • ⁠Voltaren • ⁠Baumes a levres !!! • ⁠Boules kies • ⁠creme solaire","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Voila ma checklist final, t''en penses quoi ? Il me manque des choses ? Des astuces et pro tricks pour de l''ultra ? On dort à l''hotel","position":{"start":{"line":1,"column":1,"offse