course à pied hyper leger que j’utilise pour dormir • ⁠1x legging Decath si grand froid ou soir (rarement utilisé ou pas utilisé je crois)\n💧 ","position":{"start":{"line":6,"column":15,"offset":452},"end":{"line":7,"column":4,"offset":1059}}},{"type":"emphasis","children":[{"type":"text","value":"Hydratation / nutrition","position":{"start":{"line":7,"column":5,"offset":1060},"end":{"line":7,"column":28,"offset":1083}}}],"position":{"start":{"line":7,"column":4,"offset":1059},"end":{"line":7,"column":29,"offset":1084}}},{"type":"text","value":" • 2 grandes gourdes • Salt caps (2/jour) • ⁠doses préparées de malto/fructo • ⁠qlqs gels (puis achetés en route)\n📱 ","position":{"start":{"line":7,"column":29,"offset":1084},"end":{"line":8,"column":4,"offset":1201}}},{"type":"emphasis","children":[{"type":"text","value":"Tech","position":{"start":{"line":8,"column":5,"offset":1202},"end":{"line":8,"column":9,"offset":1206}}}],"position":{"start":{"line":8,"column":4,"offset":1201},"end":{"line":8,"column":10,"offset":1207}}},{"type":"text","value":" • GPS • Écouteurs • ⁠1 chargeur rapide (tel+GPS)\n🔧 ","position":{"start":{"line":8,"column":10,"offset":1207},"end":{"line":9,"column":4,"offset":1260}}},{"type":"emphasis","children":[{"type":"text","value":"Mécanique","position":{"start":{"line":9,"column":5,"offset":1261},"end":{"line":9,"column":14,"offset":1270}}}],"position":{"start":{"line":9,"column":4,"offset":1260},"end":{"line":9,"column":15,"offset":1271}}},{"type":"text","value":" • 2 chambres à air • 1 multi tool • ⁠2 demonte pneus • ⁠1 pompe • ⁠2 capsules de CO2 • ⁠1 quick link\n📋 ","position":{"start":{"line":9,"column":15,"offset":1271},"end":{"line":10,"column":4,"offset":1376}}},{"type":"emphasis","children":[{"type":"text","value":"Divers","position":{"start":{"line":10,"column":5,"offset":1377},"end":{"line":10,"column":11,"offset":1383}}}],"position":{"start":{"line":10,"column":4,"offset":1376},"end":{"line":10,"column":12,"offset":1384}}},{"type":"text"